// EFFORT MODEL overlay (docs/EFFORT_MODEL.md, slice S1). Read ONLY while TUNING.effortModel is ON; default OFF = today's levels.
// The table lives in effortOverlay.json and is generated by tools/effort-fit.ts (never hand-edited).
import raw from './effortOverlay.json';

export interface EffortEntry {
  /** boss (last machine) HP multiplier */
  bossHpMult: number;
  /** minion pool HP multiplier */
  minionHpMult: number;
  /** per-hit cap fraction on the boss stage only (cap lever); absent = TUNING.cascadeCap */
  bossCap?: number;
}

export const EFFORT_OVERLAY = (raw as unknown as { levels: Record<string, EffortEntry> }).levels;

export const effortFor = (level: number): EffortEntry | undefined => EFFORT_OVERLAY[String(level)];

/** HP values in levels.json are multiples of 50 */
export const r50 = (x: number) => Math.max(50, Math.round(x / 50) * 50);
